mapper.update:
/** [sql-partsInput.xml] PartsInputMapper.updateOfPdStock **/
UPDATE TB_ST_01
 -- 재고 차감 (출고등록/입고삭제)
	SET ST01_QTY = ST01_QTY - #{outQty}

 -- 재고 증가 (입고등록/출고삭제)
	SET ST01_QTY = ST01_QTY + #{outQty}

WHERE 1=1
AND ST01_COMPANY = #{company}
AND ST01_FACTORY = #{factory}
AND ST01_CODE = #{code}
AND ST01_STOK = #{stock}

	AND ST01_LOT = #{lot}
	AND ST01_LOT_SEQ = #{lotSeq}

mapper.insert:
/** [sql-partsInput.xml] PartsInputMapper.updateOfSmdOutStock **/
INSERT INTO TB_ST_03
(
	ST03_COMPANY
	,ST03_FACTORY
	,ST03_NO
	,ST03_DAT
	,ST03_SEQ
	,ST03_CODE
	,ST03_LOT
	,ST03_GBN
	,ST03_PCC
	,ST03_NAPNO
	,ST03_UNT
	,ST03_QTY
	,ST03_RMK
	,ST03_STOK
	,ST03_INDTE
	,ST03_EMPNO
	,ST03_DGBN
	,ST03_QR
	,ST03_OUTPUT_NO
	,ST03_RENO
	,ST03_RTNO
	,ST03_OUTPUT_DTL_NO
	,ST03_DIST
	,ST03_SBNO
	,ST03_CUS
	,ST03_LOT_SEQ
	,ST03_LINE
	,ST03_MOQ
	,ST03_MST_NO
	,ST03_EQUIP_CODE
) VALUES (
	#{company}
	,#{factory}
	,(TO_CHAR(SYSDATE,'YYYYMMDD') || (SELECT LPAD(NVL(MAX(ST03.ST03_SEQ),0)+1,5,0) FROM TB_ST_03 ST03 WHERE TO_CHAR(SYSDATE,'YYYYMMDD') = SUBSTR(ST03.ST03_NO,0,8)))
	,TO_DATE(TO_CHAR(SYSDATE, 'YYYY-MM-DD'), 'YYYY-MM-DD')
	,(SELECT NVL(MAX(ST03.ST03_SEQ),0)+1 FROM TB_ST_03 ST03 WHERE TO_CHAR(SYSDATE,'YYYYMMDD') = SUBSTR(ST03.ST03_NO,0,8))
	,#{st02Code}
	,#{st02Lot}
	,'PT'
	,#{mf02Pcc}
	,''
	,#{st02Ipunt}
	,#{st02Ipqty}
	,''
	,#{st02Stok}
	,SYSDATE
	,#{st02Empno}
	,''
	,#{st02Qrcode}
	,''
	,''
	,''
	,''
	,#{st02Dist}
	,''
	,#{st02Cus}
	,#{st02LotSeq}
	,#{st02Line}
	,#{st02Moq}
	,#{mf02No}
	,#{st03EquipCode}
)

/** [sql-partsInput.xml] PartsInputMapper.createMfOrder **/
SELECT (TO_CHAR(SYSDATE,'YYYYMMDD') || (SELECT LPAD(NVL(MAX(MF01.MF01_SEQ),0)+1,5,0) FROM TB_MF_01 MF01 WHERE TO_CHAR(SYSDATE,'YYYYMMDD') = SUBSTR(MF01.MF01_PCC,0,8))) FROM DUAL
INSERT INTO TB_MF_01 ( MF01_COMPANY , MF01_FACTORY , MF01_PCC , MF01_DAT , MF01_GBN , MF01_NO , MF01_SEQ , MF01_CODE , MF01_PGBN , MF01_QTY , MF01_WANYN , MF01_STOK , MF01_REV , MF01_RMK , MF01_INDTE , MF01_EMPNO , MF01_MPGBN , MF01_DRYGBN ) VALUES ( #{company} , #{factory} , #{mf01Pcc} , TO_CHAR(SYSDATE,'YYYY-MM-DD') , '2' , '' , SUBSTR(#{mf01Pcc},9,5) , #{compMfCode} , '' , #{compMfQty} , 'N' , '' , '' , '' , SYSDATE , #{empNo} , 'N' , 'N' )

/** [sql-partsInput.xml] PartsInputMapper.createMfOrderDetail **/

	SELECT (#{mf02Pcc} || (SELECT LPAD(NVL(MAX(MF02.MF02_SEQ),0)+1,5,0) FROM TB_MF_02 MF02 WHERE #{mf02Pcc} = SUBSTR(MF02.MF02_PCC,0,13))) FROM DUAL

INSERT INTO TB_MF_02
(
	MF02_COMPANY
	,MF02_FACTORY
	,MF02_PCC
	,MF02_NO
	,MF02_SEQ
	,MF02_CODE
	,MF02_GBN
	,MF02_QTY
	,MF02_UNT
	,MF02_INDTE
	,MF02_LOT_SEQ
)
VALUES
(
	  #{company}
	, #{factory}
	, #{mf02Pcc}
	, #{mf02No}
	, SUBSTR(#{mf02No},14,18)
	, #{st02Code}
	, ''
	, #{st02Ipqty}
	, #{st02Ipunt}
	, SYSDATE
	, #{st02LotSeq}
)

mapper.select:
SELECT CM08.*, (CM08.CM08_NAME || '[' || CM08.CM08_CODE || ']') AS MF_DISP
FROM TB_CM_08 CM08
WHERE 1=1 
AND CM08.CM08_COMPANY = #{company}
AND CM08.CM08_FACTORY = #{factory}
AND CM08.CM08_SMD = #{cm08Smd}
